		validator.validate( command );

            entity.setSalesContractId( command.getSalesContractId() );
            entity.setContractNumber( command.getContractNumber() );
            entity.setPrice( command.getPrice() );
            entity.setQuantity( command.getQuantity() );
            entity.setDeliveryDate( command.getDeliveryDate() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
